<?php require_once "../includes/auth.php"; require_admin(); $db=db(); $cats=$db->query("SELECT cat.category_name,COUNT(c.complaint_id) total FROM categories cat LEFT JOIN complaints c ON c.category_id=cat.category_id GROUP BY cat.category_id ORDER BY total DESC")->fetchAll(); $avg=$db->query("SELECT ROUND(AVG(rating),2) avg_rating,ROUND(AVG(food_rating),2) food,ROUND(AVG(service_rating),2) service,ROUND(AVG(cleanliness_rating),2) clean,ROUND(AVG(value_rating),2) value FROM feedback")->fetch(); include "../includes/header.php"; ?>
<div class="dashboard container"><a href="dashboard.php">← Dashboard</a><h1>Reports & Statistics</h1><div class="stats"><div><small>Overall</small><strong><?= $avg["avg_rating"]?: "—" ?>/5</strong></div><div><small>Food</small><strong><?= $avg["food"]?: "—" ?>/5</strong></div><div><small>Service</small><strong><?= $avg["service"]?: "—" ?>/5</strong></div><div><small>Cleanliness</small><strong><?= $avg["clean"]?: "—" ?>/5</strong></div><div><small>Value</small><strong><?= $avg["value"]?: "—" ?>/5</strong></div></div><div class="table-card"><h2>Complaints by Category</h2><table><tr><th>Category</th><th>Total Complaints</th></tr><?php foreach($cats as $c): ?><tr><td><?= e($c["category_name"]) ?></td><td><?= e($c["total"]) ?></td></tr><?php endforeach; ?></table></div></div>
